import React from "react";
import { warnMissingProp } from "./dev-warning";

// ProcedureRecordList: a list of a patient's procedures, whose status is never blank (tasks.md P28-T3, spec/healthcare-ui).
// For any status but "known", statusLabel is the list's one item. Props and rules: ProcedureRecordList.md.

export interface ProcedureRecordListProps {
    className?: string;
    status: "known" | "none-known" | "not-recorded" | "unavailable" | "omitted";
    /** The consumer's words for the status; names the list, and is its one item unless status is "known". */
    statusLabel: string;
    /** The accessible name, when it should differ from statusLabel. */
    label?: string;
    children?: React.ReactNode;
    [key: string]: unknown;
}

export default function ProcedureRecordList({
    className = "",
    status,
    statusLabel,
    label,
    children,
    ...restProps
}: ProcedureRecordListProps) {
    warnMissingProp(
        "ProcedureRecordList",
        "status",
        status,
        "A procedure record list must say whether procedures are known, none known, not recorded, unavailable or omitted.",
    );
    warnMissingProp(
        "ProcedureRecordList",
        "statusLabel",
        statusLabel,
        "The status needs words a person can read.",
    );
    return (
        <ul
            className={`procedure-record-list ${className}`}
            data-status={status}
            aria-label={label ?? statusLabel}
            {...restProps}
        >
            {status !== "known" ? (
                <li className="procedure-record-list-status">{statusLabel}</li>
            ) : null}
            {children}
        </ul>
    );
}
